#include <stdio.h>
#include <math.h>

typedef struct { float x, y, z; } V;

static V v(float x, float y, float z) { V r; r.x = x; r.y = y; r.z = z; return r; }
static V add(V a, V b) { return v(a.x + b.x, a.y + b.y, a.z + b.z); }
static V sub(V a, V b) { return v(a.x - b.x, a.y - b.y, a.z - b.z); }
static V mul(V a, float s) { return v(a.x * s, a.y * s, a.z * s); }
static float dot(V a, V b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
static V norm(V a) { float l = sqrtf(dot(a, a)); return l > 0.0f ? mul(a, 1.0f / l) : a; }

typedef struct { V o, d; } Ray;
typedef struct { int hit; float t; V p, n; } Hit;

static Ray mkray(V o, V d) { Ray r; r.o = o; r.d = norm(d); return r; }
static V at(Ray r, float t) { return add(r.o, mul(r.d, t)); }

static V SC = { 0.0f, -0.5f, -5.0f };
static const float SR = 1.0f;
static const float PY = -1.5f;
static const float EPS = 1e-3f;

static Hit sphere_hit(Ray r)
{
    Hit h; h.hit = 0; h.t = 0.0f; h.p = v(0, 0, 0); h.n = v(0, 0, 0);
    V oc = sub(r.o, SC);
    float a = dot(r.d, r.d);
    float b = 2.0f * dot(oc, r.d);
    float c = dot(oc, oc) - SR * SR;
    float disc = b * b - 4.0f * a * c;
    if (disc < 0.0f) return h;
    float sd = (float)sqrt((double)disc);
    float t = (float)(((double)(-b) - (double)sd) / (double)(2.0f * a));
    if (t < EPS) {
        t = (float)(((double)(-b) + (double)sd) / (double)(2.0f * a));
        if (t < EPS) return h;
    }
    h.hit = 1;
    h.t = t;
    h.p = at(r, t);
    h.n = norm(sub(h.p, SC));
    return h;
}

static Hit plane_hit(Ray r)
{
    Hit h; h.hit = 0; h.t = 0.0f; h.p = v(0, 0, 0); h.n = v(0, 0, 0);
    if (fabsf(r.d.y) < 1e-4f) return h;
    float t = (PY - r.o.y) / r.d.y;
    if (t < EPS) return h;
    h.hit = 1;
    h.t = t;
    h.p = at(r, t);
    h.n = v(0.0f, 1.0f, 0.0f);
    return h;
}

static V sky(Ray r)
{
    float t = 0.5f * (r.d.y + 1.0f);
    return add(mul(v(0.5f, 0.7f, 1.0f), t), mul(v(1.0f, 1.0f, 1.0f), 1.0f - t));
}

static int shadowed(V p, V ld)
{
    Ray s = mkray(p, ld);
    return sphere_hit(s).hit;
}

static V trace(Ray r, V ld)
{
    Hit hs = sphere_hit(r);
    Hit hp = plane_hit(r);
    Hit h; int is_sphere = 0;
    h.hit = 0; h.t = 0.0f; h.p = v(0, 0, 0); h.n = v(0, 0, 0);
    if (hs.hit && (!hp.hit || hs.t <= hp.t)) {
        h = hs; is_sphere = 1;
    } else if (hp.hit) {
        h = hp; is_sphere = 0;
    } else {
        return sky(r);
    }
    float diff = dot(h.n, ld);
    if (diff < 0.0f) diff = 0.0f;
    if (shadowed(add(h.p, mul(h.n, EPS)), ld)) diff = 0.0f;
    float amb = 0.2f;
    float inten = amb + (1.0f - amb) * diff;
    if (is_sphere) return mul(v(1.0f, 0.2f, 0.2f), inten);
    int even = (((int)(floor((double)h.p.x) + floor((double)h.p.z))) & 1) == 0;
    float g = even ? 0.9f : 0.4f;
    return mul(v(g, g, g), inten);
}

int main(void)
{
    const int W = 2400, H = 1800;
    V origin = v(0.0f, 0.0f, 0.0f);
    float vh = 2.0f;
    float vw = ((float)W / (float)H) * vh;
    float focal = 1.0f;
    V horiz = v(vw, 0.0f, 0.0f);
    V vert = v(0.0f, vh, 0.0f);
    V depth = v(0.0f, 0.0f, focal);
    V ll = sub(sub(sub(origin, mul(horiz, 0.5f)), mul(vert, 0.5f)), depth);
    V ld = norm(v(1.0f, 1.0f, -1.0f));

    FILE *f = fopen("reconstructed.ppm", "w");
    if (!f) return 1;
    fprintf(f, "P3\n%d %d\n255\n", W, H);
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            float u = (float)x / (float)(W - 1);
            float vv = (float)y / (float)(H - 1);
            V dir = add(ll, add(mul(horiz, u), sub(mul(vert, 1.0f - vv), origin)));
            V col = trace(mkray(origin, dir), ld);
            double cr = fmin(fmax((double)col.x, 0.0), 1.0);
            double cg = fmin(fmax((double)col.y, 0.0), 1.0);
            double cb = fmin(fmax((double)col.z, 0.0), 1.0);
            int ir = (int)(255.99f * (float)cr);
            int ig = (int)(255.99f * (float)cg);
            int ib = (int)(255.99f * (float)cb);
            fprintf(f, "%d %d %d\n", ir, ig, ib);
        }
    }
    fclose(f);
    return 0;
}

